#include <stdio.h>

int main(void) {
    int S, T;
    if (scanf("%d %d", &S, &T) != 2) return 0;

    static unsigned char adj[1001][1001] = {0};

    for (int i = 0; i < T; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        adj[x][y] = 1;
        adj[y][x] = 1;
    }

    int P;
    scanf("%d", &P);

    int ans = 0;

    for (int q = 0; q < P; q++) {
        int N;
        scanf("%d", &N);

        int prev;
        scanf("%d", &prev);

        int ok = 1;

        for (int i = 1; i < N; i++) {
            int cur;
            scanf("%d", &cur);

            if (ok && !adj[prev][cur]) {
                ok = 0;
            }

            prev = cur;
        }

        if (ok) ans++;
    }

    printf("%d\n", ans);

    return 0;
}
